-- Which of the migrations are in, and did each one take? Paste into the Supabase SQL editor.
-- One row. A column that belongs to a migration you have run must say true.
--   0115, 0116, 0117, 0118 and 0120 belong to both projects; 0119 and 0121 only to the sandbox project (false is right on the real one).
--   Run it BEFORE the migrations to see which are already in (false = not run yet), and AFTER to confirm.
-- Reads only; changes nothing. Generated from each migration's own list of what it creates, so these are
-- "is it there" checks; 0115 and 0116 also end with their own, stricter checks row.

select
  ((select bool_and(exists(select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = split_part(x, '.', 1) and p.proname = split_part(x, '.', 2))) from unnest(array['public.admin_network_health', 'public.choose_referral_colleague', 'public.consultation_useful_marks', 'public.guard_referral_response_change', 'public.react_to_message', 'public.respond_continuity', 'public.set_response_useful']) x)) as "m0115",
  ((select bool_and(to_regclass('public.' || n) is not null) from unnest(array['suggested_colleagues', 'suggestion_runs']) n) and (select bool_and(exists(select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = split_part(x, '.', 1) and p.proname = split_part(x, '.', 2))) from unnest(array['private.grant_founding_place', 'public.founding_places_left', 'public.guard_message_change', 'public.my_colleague_affinity', 'public.sandbox_tick', 'public.set_my_suggestions']) x)) as "m0116",
