  ((select bool_and(to_regclass('public.' || n) is not null) from unnest(array['consultation_follows', 'consultation_response_useful', 'saved_resources']) n) and (select bool_and(exists(select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = split_part(x, '.', 1) and c.column_name = split_part(x, '.', 2))) from unnest(array['consultation_responses.client_response_id', 'consultations.client_request_id', 'consultations.topic']) x) and (select bool_and(exists(select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = split_part(x, '.', 1) and p.proname = split_part(x, '.', 2))) from unnest(array['private.consult_can_see', 'private.consult_recent', 'private.discussion_json', 'public.consult_follow', 'public.consult_post', 'public.consult_reply', 'public.consult_useful', 'public.my_consult_follows', 'public.my_consult_useful', 'public.my_saved_resources', 'public.resource_save', 'public.set_workspace_preference', 'public.trust_set', 'public.workspace_boot', 'public.workspace_consult', 'public.workspace_discussion', 'public.workspace_discussions', 'public.workspace_groups', 'public.workspace_known', 'public.workspace_preferences', 'public.workspace_resources', 'public.workspace_slice', 'public.workspace_tiers']) x)) as "m0118",
  ((select bool_and(to_regclass('public.' || n) is not null) from unnest(array['referral_titles']) n) and (select bool_and(exists(select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = split_part(x, '.', 1) and c.column_name = split_part(x, '.', 2))) from unnest(array['referral_requests.member_seq']) x) and (select bool_and(exists(select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = split_part(x, '.', 1) and p.proname = split_part(x, '.', 2))) from unnest(array['private.activate_member_invites', 'private.consult_no_reply_when_resolved', 'private.cover_case_exclusions', 'private.cover_exclusions', 'private.is_active_clinician', 'private.licence_route', 'private.licensed_for', 'private.referral_assign_number', 'private.referral_exclusions', 'private.referral_json', 'private.referral_label', 'private.referral_title_problem', 'public.consult_resolve', 'public.cover_answer', 'public.guard_referral_response', 'public.message_edit', 'public.my_availability', 'public.referral_answer', 'public.referral_create', 'public.referral_set_title', 'public.set_my_availability', 'public.workspace_inbound', 'public.workspace_me', 'public.workspace_people', 'public.workspace_physician_referrals', 'public.workspace_tiers']) x)) as "m0120",
  ((select bool_and(exists(select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = split_part(x, '.', 1) and c.column_name = split_part(x, '.', 2))) from unnest(array['consultations.sandbox_owner']) x) and (select bool_and(exists(select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = split_part(x, '.', 1) and p.proname = split_part(x, '.', 2))) from unnest(array['private.clear_demo_viewer', 'private.consult_can_see', 'private.consult_recent', 'private.demo_as', 'private.demo_autorespond', 'private.demo_case', 'private.demo_cast', 'private.demo_cast_ids', 'private.demo_client', 'private.demo_conv', 'private.demo_discussions', 'private.demo_open_clock', 'private.demo_req', 'private.demo_restore', 'private.demo_shift', 'private.demo_thread', 'private.demo_threads', 'private.is_sandbox_colleague', 'private.notify_member', 'private.professional_event', 'private.sandbox_story_event', 'private.seed_demo_cast', 'private.seed_demo_viewer', 'private.seed_demo_viewer_story', 'private.stamp_sandbox_owner', 'private.suppress_demo_delivery', 'public.claim_sandbox', 'public.sandbox_confirmation', 'public.sandbox_example', 'public.sandbox_info', 'public.sandbox_respond', 'public.sandbox_tick']) x)) as "m0119_sandbox_only",
  ((select bool_and(exists(select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = split_part(x, '.', 1) and p.proname = split_part(x, '.', 2))) from unnest(array['private.seed_demo_viewer_story', 'private.seed_final_extras']) x)) as "m0121_sandbox_only";
